mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM videos
    WHERE id = #{videoId}
)

SELECT EXISTS(
    SELECT 1
    FROM likes
    WHERE video_id = #{videoId}
      AND account_id = #{accountId}
)

mapper.delete:
DELETE FROM likes
WHERE video_id = #{videoId}
  AND account_id = #{accountId}

mapper.select:
SELECT 
FROM likes l
INNER JOIN videos v ON v.id = l.video_id
WHERE l.account_id = #{accountId}
ORDER BY l.created_at DESC
LIMIT #{limit}
